package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.aliothmoon.maafw.once.BingNavigationFixture.*;
/** Synthetic strict metadata grammar; does not wrap a legacy Ready or any recovery enum as proof. */
public class CurrentTemplateProofTest {
 static BingNavigationSnapshot.CurrentTemplateResult parse(String w,String a){return BingNavigationSnapshot.parseCurrentTemplate(w,a,PROFILE,RootReadOnlyAnimationGuardTest.G,1000,1010);}
 static String w(){return RootReadOnlyAnimationGuardTest.w();}static String a(){return RootReadOnlyAnimationGuardTest.a();}
 @Test public void onlyFreshStrictTemplateCreatesCurrentToken(){var r=parse(w(),a());assertEquals(BingNavigationSnapshot.Status.READY,r.status());assertNotNull(r.source());assertEquals(BingNavigationSnapshot.Kind.TEMPLATE,r.source().ready().kind());assertTrue(r.source().fresh(1010));assertFalse(r.source().fresh(6001));assertEquals(BingNavigationSnapshot.ReadOnlyGate.METADATA_STABLE_ONLY,r.readOnlyGate());}
 @Test public void browserReadyDoesNotBecomeCurrentTemplateProof(){var r=parse(w().replace(BingNavigationSnapshot.TEMPLATE,BingNavigationSnapshot.BROWSER),a().replace(BingNavigationSnapshot.TEMPLATE,BingNavigationSnapshot.BROWSER));assertEquals(BingNavigationSnapshot.Status.UNKNOWN,r.status());assertNull(r.source());assertEquals(BingNavigationSnapshot.FirstGate.CURRENT_TEMPLATE_REQUIRED,r.firstGate());}
 @Test public void legacyReadyOrMissingOwnDrawCannotMintToken(){var r=parse(windows(BingNavigationSnapshot.TEMPLATE,"aaa","ddd","15"),activities(BingNavigationSnapshot.TEMPLATE,"ddd","15",true));assertEquals(BingNavigationSnapshot.Status.UNKNOWN,r.status());assertNull(r.source());assertNull(BingNavigationSnapshot.parseCurrentTemplate(w(),a(),PROFILE,null,1000,1010).source());}
 @Test public void knownDrawTransitionIsStillBoundedTransitionWithoutSource(){var r=parse(w().replace("HAS_DRAWN","DRAW_PENDING"),a());assertEquals(BingNavigationSnapshot.Status.BING_TRANSITION,r.status());assertNull(r.source());assertEquals(BingNavigationSnapshot.ReadOnlyGate.TARGET_DRAW,r.readOnlyGate());}
 @Test public void unknownFocusConflictRemainsUnknownNotPollable(){var r=parse(w().replace("mFocusedApp=ActivityRecord{ddd u0 "+BingNavigationSnapshot.TEMPLATE,"mFocusedApp=ActivityRecord{ddd u0 "+BingNavigationSnapshot.BROWSER),a());assertEquals(BingNavigationSnapshot.Status.UNKNOWN,r.status());assertNull(r.source());assertEquals(BingNavigationSnapshot.FirstGate.FOCUS_COMPONENT_CONFLICT,r.firstGate());}
 @Test public void noFreshTokenFromExpiredOrUnknownOwnWindow(){assertNull(BingNavigationSnapshot.parseCurrentTemplate(w(),a(),PROFILE,RootReadOnlyAnimationGuardTest.G,1000,7000).source());assertNull(parse(w().replace("mDrawState=NO_SURFACE","missingDraw"),a()).source());}
 @Test public void anchorMatchesOnlyExactCurrentTemplateSource(){var r=parse(w(),a());assertTrue(r.source().matches(parse(w(),a()).source().ready()));assertFalse(r.source().matches(BingNavigationFixture.result(BingNavigationSnapshot.Kind.BROWSER,1000).ready()));assertFalse(r.source().matches(parse(w().replace("Window{aaa u0","Window{abb u0"),a()).source().ready()));}
 @Test public void noPublicConstructorOrRawIdentityInSummary(){for(var c:BingNavigationSnapshot.CurrentTemplateSource.class.getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(c.getModifiers()));var r=parse(w(),a());String out=r.summary()+r.source().summary();assertFalse(out.contains("aaa"));assertFalse(out.contains("ddd"));assertFalse(out.contains("ActivityRecord"));assertTrue(out.length()<500);}
}
